!function(t){"use strict";var n=t.TruyenTong={};n.COST=10,n.REACH=56,n.PADS=[{id:"tt_tan_vien",map:"tan_vien",tx:31,ty:12,to:"tt_dai_tan",label:"Thành Thăng Long"},{id:"tt_dai_tan",map:"bat_quai_thach_phan",tx:33,ty:23,to:"tt_tan_vien",label:"Chân Núi Tản Viên"}],n.pad=function(t){for(var r=0;r<n.PADS.length;r++)if(n.PADS[r].id===t)return n.PADS[r];return null},n.padsOf=function(t){return n.PADS.filter(function(n){return n.map===t})},n.center=function(n){var r=t.CONFIG.TILE;return{x:(n.tx+.5)*r,y:(n.ty+.5)*r}},n.padAt=function(t,r,a){for(var e=n.padsOf(t),i=0;i<e.length;i++){var h=n.center(e[i]),o=h.x-r,u=1.4*(h.y-a);if(o*o+u*u<=n.REACH*n.REACH)return e[i]}return null},n.pay=function(t){var r=t&&t.Progress;return!r||(0|r.stones)<n.COST?{ok:!1,why:"không đủ "+n.COST+" Linh Thạch"}:r.spendStones(n.COST)?{ok:!0,cost:n.COST,stones:0|r.stones}:{ok:!1,why:"không đủ "+n.COST+" Linh Thạch"}},n.PADS.forEach(function(r){var a=t.MapData&&t.MapData.get(r.map);a&&(a.interactables=(a.interactables||[]).filter(function(t){return t.id!==r.id}),a.interactables.push({id:r.id,tx:r.tx,ty:r.ty,r:n.REACH,title:"Truyền Tống Trận",text:"Trận pháp cổ nối thẳng tới "+r.label+".\nMỗi lượt truyền tống tốn "+n.COST+" Linh Thạch."}))})}(window.PNTT);
;
