!function(n){"use strict";var h={mieu_hoang:30,duoc_vien:30,hang_dong_co:30},o={tan_vien:[[17,19]],mieu_hoang:[[16,5]],thanh_truc_lam:[[10,3],[15,27]],duoc_vien:[[15,4]],hang_dong_co:[[11,17]],bai_da_hang_gio:[[5,26],[18,12]],mo_linh_thach:[[4,11],[33,14]],dong_mach_ngam:[[11,22]]};Object.keys(o).forEach(function(a){var _=n.MapData.get(a);_&&_.id===a?(_.khu=h[a]||20,_.props=_.props||[],o[a].forEach(function(n,h){_.props.push({id:"bang_khu_"+(h+1),type:"khu_board",tx:n[0],ty:n[1],r:44,block:!1,name:"Bảng Khu"})})):console.error("[PNTT] Chia khu: không thấy bản đồ "+a)}),n.Khu=n.Khu||{},n.Khu.SO_KHU=20,n.Khu.SO_KHU_RIENG=h}(window.PNTT);